CREATE TRIGGER quotes_snapshot_no_update BEFORE UPDATE ON quotes FOR EACH ROW BEGIN IF NOT ((OLD.`id` <=> NEW.`id`) AND (OLD.`design_id` <=> NEW.`design_id`) AND (OLD.`user_id` <=> NEW.`user_id`) AND (OLD.`version` <=> NEW.`version`) AND (OLD.`currency` <=> NEW.`currency`) AND (OLD.`subtotal_minor` <=> NEW.`subtotal_minor`) AND (OLD.`tax_minor` <=> NEW.`tax_minor`) AND (OLD.`total_minor` <=> NEW.`total_minor`) AND (OLD.`deposit_minor` <=> NEW.`deposit_minor`) AND (OLD.`estimated_cost_minor` <=> NEW.`estimated_cost_minor`) AND (OLD.`tax_bps` <=> NEW.`tax_bps`) AND (OLD.`lines` <=> NEW.`lines`) AND (OLD.`specification` <=> NEW.`specification`) AND (OLD.`delivery_terms` <=> NEW.`delivery_terms`) AND (OLD.`terms` <=> NEW.`terms`) AND (OLD.`approval_reference` <=> NEW.`approval_reference`) AND (OLD.`expires_at` <=> NEW.`expires_at`) AND (OLD.`created_by` <=> NEW.`created_by`) AND (OLD.`created_at` <=> NEW.`created_at`)) OR (OLD.accepted_at IS NOT NULL AND NOT (OLD.accepted_at <=> NEW.accepted_at)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Approved financial snapshots are immutable'; END IF; END;
CREATE TRIGGER quotes_no_delete BEFORE DELETE ON quotes FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Financial history cannot be deleted';
CREATE TRIGGER orders_snapshot_no_update BEFORE UPDATE ON orders FOR EACH ROW BEGIN IF NOT ((OLD.`id` <=> NEW.`id`) AND (OLD.`user_id` <=> NEW.`user_id`) AND (OLD.`quote_id` <=> NEW.`quote_id`) AND (OLD.`design_id` <=> NEW.`design_id`) AND (OLD.`currency` <=> NEW.`currency`) AND (OLD.`subtotal_minor` <=> NEW.`subtotal_minor`) AND (OLD.`tax_minor` <=> NEW.`tax_minor`) AND (OLD.`total_minor` <=> NEW.`total_minor`) AND (OLD.`deposit_minor` <=> NEW.`deposit_minor`) AND (OLD.`snapshot` <=> NEW.`snapshot`) AND (OLD.`accepted_terms_at` <=> NEW.`accepted_terms_at`) AND (OLD.`created_at` <=> NEW.`created_at`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Approved financial snapshots are immutable'; END IF; END;
CREATE TRIGGER orders_no_delete BEFORE DELETE ON orders FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Financial history cannot be deleted';
CREATE TRIGGER invoices_no_update BEFORE UPDATE ON invoices FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Financial history is append-only';
CREATE TRIGGER invoices_no_delete BEFORE DELETE ON invoices FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Financial history is append-only';
